 "content": "def transform(grid):
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda v: sum(r.count(v) for r in grid))
    mark = next(v for v in colors if v != bg)
    for r, row in enumerate(grid):
        cols = [c for c, v in enumerate(row) if v == mark]
        for a, b in zip(cols, cols[1:]):
